   206  static exr_result_t
   207  decompress_data (
   208      const struct _internal_exr_context* pctxt,
   209      const exr_compression_t             ctype,
   210      exr_decode_pipeline_t*              decode,
   211      void*                               packbufptr,
   212      size_t                              packsz,
   213      void*                               unpackbufptr,
   214      size_t                              unpacksz)
   215  {
   216      exr_result_t rv;
   217
   218      if (packsz == 0) return EXR_ERR_SUCCESS;
   219
   220      if (packsz == unpacksz && ctype != EXR_COMPRESSION_B44 &&
   221          ctype != EXR_COMPRESSION_B44A)
   222      {
   223          if (unpackbufptr != packbufptr)
   224              memcpy (unpackbufptr, packbufptr, unpacksz);
   225          return EXR_ERR_SUCCESS;
   226      }
   227
   228      switch (ctype)
   229      {
   230          case EXR_COMPRESSION_NONE:
   231              return pctxt->report_error (
   232                  pctxt,
   233                  EXR_ERR_INVALID_ARGUMENT,
   234                  "no compression set but still trying to decompress");
   235
   236          case EXR_COMPRESSION_RLE:
   237              rv = internal_exr_undo_rle (
   238                  decode, packbufptr, packsz, unpackbufptr, unpacksz);
   239              break;
   240          case EXR_COMPRESSION_ZIP:
   241          case EXR_COMPRESSION_ZIPS:
   242              rv = internal_exr_undo_zip (
   243                  decode, packbufptr, packsz, unpackbufptr, unpacksz);
   244              break;
   245          case EXR_COMPRESSION_PIZ:
   246              rv = internal_exr_undo_piz (
   247                  decode, packbufptr, packsz, unpackbufptr, unpacksz);
   248              break;
   249          case EXR_COMPRESSION_PXR24:
   250              rv = internal_exr_undo_pxr24 (
   251                  decode, packbufptr, packsz, unpackbufptr, unpacksz);
   252              break;
   253          case EXR_COMPRESSION_B44:
   254              rv = internal_exr_undo_b44 (
   255                  decode, packbufptr, packsz, unpackbufptr, unpacksz);
   256              break;
   257          case EXR_COMPRESSION_B44A:
   258              rv = internal_exr_undo_b44a (
   259                  decode, packbufptr, packsz, unpackbufptr, unpacksz);
   260              break;
   261          case EXR_COMPRESSION_DWAA:
   262              rv = internal_exr_undo_dwaa (
   263                  decode, packbufptr, packsz, unpackbufptr, unpacksz);
   264              break;
   265          case EXR_COMPRESSION_DWAB:
   266              rv = internal_exr_undo_dwab (
   267                  decode, packbufptr, packsz, unpackbufptr, unpacksz);
   268              break;
   269          case EXR_COMPRESSION_LAST_TYPE:
   270          default:
   271              return pctxt->print_error (
   272                  pctxt,
   273                  EXR_ERR_INVALID_ARGUMENT,
   274                  "Compression technique 0x%02X invalid",
   275                  ctype);
   276      }
   277
   278      return rv;
   279  }
   280
   281  static exr_result_t
   282  default_decompress_chunk (exr_decode_pipeline_t* decode)
   283  {
   284      exr_result_t rv = EXR_ERR_SUCCESS;
   285      EXR_PROMOTE_READ_CONST_CONTEXT_AND_PART_OR_ERROR (
   286          decode->context, decode->part_index);
   287
   288      if (part->storage_mode == EXR_STORAGE_DEEP_SCANLINE ||
   289          part->storage_mode == EXR_STORAGE_DEEP_TILED)
   290      {
   291          uint64_t sampsize =
   292              (((uint64_t) decode->chunk.width) *
   293               ((uint64_t) decode->chunk.height));
   294          sampsize *= sizeof (int32_t);
   295
   296          rv = decompress_data (
   297              pctxt,
   298              part->comp_type,
   299              decode,
   300              decode->packed_sample_count_table,
   301              decode->chunk.sample_count_table_size,
   302              decode->sample_count_table,
   303              sampsize);
   304
   305          if (rv != EXR_ERR_SUCCESS)
   306          {
   307              return pctxt->print_error (
   308                  pctxt,
   309                  rv,
   310                  "Unable to decompress sample table %" PRIu64 " -> %" PRIu64,
   311                  decode->chunk.sample_count_table_size,
   312                  (uint64_t) sampsize);
   313          }
   314          if ((decode->decode_flags & EXR_DECODE_SAMPLE_DATA_ONLY)) return rv;
   315      }
   316
   317      if (rv == EXR_ERR_SUCCESS)
   318          rv = decompress_data (
   319              pctxt,
   320              part->comp_type,
   321              decode,
   322              decode->packed_buffer,
   323              decode->chunk.packed_size,
   324              decode->unpacked_buffer,
   325              decode->chunk.unpacked_size);
   326
   327      if (rv != EXR_ERR_SUCCESS)
   328      {
   329          return pctxt->print_error (
   330              pctxt,
   331              rv,
   332              "Unable to decompress image data %" PRIu64 " -> %" PRIu64,
   333              decode->chunk.packed_size,
   334              decode->chunk.unpacked_size);
   335      }
   336      return rv;
   337  }
   338
   339  static exr_result_t
   340  unpack_sample_table (
   341      const struct _internal_exr_context* pctxt, exr_decode_pipeline_t* decode)
   342  {
   343      exr_result_t rv           = EXR_ERR_SUCCESS;
   344      int32_t      w            = decode->chunk.width;
   345      int32_t      h            = decode->chunk.height;
   346      int32_t      totsamp      = 0;
   347      int32_t*     samptable    = decode->sample_count_table;
   348      size_t       combSampSize = 0;
   349
   350      for (int c = 0; c < decode->channel_count; ++c)
   351          combSampSize += ((size_t) decode->channels[c].bytes_per_element);
   352
   353      if ((decode->decode_flags & EXR_DECODE_SAMPLE_COUNTS_AS_INDIVIDUAL))
   354      {
   355          for (int32_t y = 0; y < h; ++y)
   356          {
   357              int32_t prevsamp = 0;
   358              for (int32_t x = 0; x < w; ++x)
   359              {
   360                  int32_t nsamps =
   360                  int32_t nsamps =
   361                      (int32_t) one_to_native32 ((uint32_t) samptable[y * w + x]);
   362                  if (nsamps < 0) return EXR_ERR_INVALID_SAMPLE_DATA;
   363                  samptable[y * w + x] = nsamps - prevsamp;
   364                  prevsamp             = nsamps;
   365              }
   366              totsamp += prevsamp;
   367          }
   368          samptable[w * h] = totsamp;
   369      }
   370      else
   371      {
   372          for (int32_t y = 0; y < h; ++y)
   373          {
   374              int32_t prevsamp = 0;
   375              for (int32_t x = 0; x < w; ++x)
   376              {
   377                  int32_t nsamps =
   378                      (int32_t) one_to_native32 ((uint32_t) samptable[y * w + x]);
   379                  if (nsamps < 0) return EXR_ERR_INVALID_SAMPLE_DATA;
   380                  samptable[y * w + x] = nsamps;
   381                  prevsamp             = nsamps;
   382              }
   383              totsamp += prevsamp;
   384          }
   385      }
   386
   387      if (totsamp < 0 ||
   388          (((uint64_t) totsamp) * combSampSize) > decode->chunk.unpacked_size)
   389      {
   390          rv = pctxt->report_error (
   391              pctxt, EXR_ERR_INVALID_SAMPLE_DATA, "Corrupt sample count table");
   392      }
   393      return rv;
   394  }
