   397
   398  exr_result_t
   399  exr_decoding_initialize (
   400      exr_const_context_t     ctxt,
   401      int                     part_index,
   402      const exr_chunk_info_t* cinfo,
   403      exr_decode_pipeline_t*  decode)
   404  {
   405      exr_result_t          rv;
   406      exr_decode_pipeline_t nil = {0};
   407
   408      EXR_PROMOTE_READ_CONST_CONTEXT_AND_PART_OR_ERROR (ctxt, part_index);
   409      if (!cinfo || !decode)
   410          return pctxt->standard_error (pctxt, EXR_ERR_INVALID_ARGUMENT);
   411
   412      *decode = nil;
   413
   414      rv = internal_coding_fill_channel_info (
   415          &(decode->channels),
   416          &(decode->channel_count),
   417          decode->_quick_chan_store,
   418          cinfo,
   419          pctxt,
   420          part);
   421
   422      if (rv == EXR_ERR_SUCCESS)
   423      {
   424          decode->part_index = part_index;
   425          decode->context    = ctxt;
   426          decode->chunk      = *cinfo;
   427      }
   428      return rv;
