   594
   595  exr_result_t
   596  exr_decoding_update (
   597      exr_const_context_t     ctxt,
   598      int                     part_index,
   599      const exr_chunk_info_t* cinfo,
   600      exr_decode_pipeline_t*  decode)
   601  {
